<template>
  <section class="grid gap-5">
    <header class="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
      <div class="min-w-0">
        <h1 class="text-2xl font-bold text-[var(--ui-text-highlighted)]">Users &amp; Access</h1>
        <div class="mt-3 flex flex-wrap gap-2">
          <UBadge color="primary" variant="subtle">{{ users.length }} users</UBadge>
          <UBadge v-if="unassignedKeyCount > 0" color="warning" variant="subtle">{{ unassignedKeyCount }} unassigned keys</UBadge>
        </div>
      </div>
      <UButton color="neutral" variant="outline" icon="i-heroicons-arrow-path" :loading="loading" @click="syncAll(true)">{{ loading ? 'Syncing' : 'Sync data' }}</UButton>
    </header>

    <UAlert v-if="capabilitiesError" color="warning" variant="subtle" title="Capability discovery failed" :description="capabilitiesError" />
    <UAlert v-if="pageErrors.length" color="warning" variant="subtle" title="Some data could not be loaded" :description="pageErrors.join(' · ')" />

    <UAlert v-if="!usersSupported" color="info" variant="subtle" title="This runtime does not expose user management" description="The connected runtime did not declare user management support. The page will not load user management tables or invent users, key ownership, or access scopes." />

    <AdminDataPanel v-else title="Access workspace">
      <template #actions>
        <UInput v-model="search" icon="i-heroicons-magnifying-glass" placeholder="Filter users, keys, or scopes" class="w-full sm:w-80" />
      </template>

      <div class="min-w-0">
        <UTabs v-model="activeTab" :items="tabs" value-key="value" label-key="label" class="w-full px-4 pt-4" />

        <div v-if="activeTab === 'users'" class="grid gap-3 p-4">
          <div class="flex justify-end"><UButton icon="i-heroicons-plus" @click="openUserCreate">New user</UButton></div>
          <div v-if="selectedUsers.length" class="flex flex-col gap-3 rounded-md border border-[var(--ui-border)] bg-[var(--ui-bg-muted)] px-3 py-2.5 lg:flex-row lg:items-center lg:justify-between">
            <div><p class="text-sm font-medium">{{ selectedUsers.length }} users selected</p><p class="mt-0.5 text-xs text-[var(--ui-text-muted)]">Bulk operations create separate balance records for each user.</p></div>
            <div class="flex flex-wrap gap-2"><UButton color="neutral" variant="ghost" @click="selectedUserIds = new Set()">Clear selection</UButton><UButton color="neutral" variant="ghost" icon="i-heroicons-banknotes" @click="openBalance(selectedUsers)">Balance operation</UButton></div>
          </div>
          <div class="overflow-x-auto rounded-md border border-[var(--ui-border)]">
            <UTable :columns="userColumns" :data="filteredUsers" :loading="loading" class="users-table min-w-[1160px]">
              <template #select-header><UCheckbox :model-value="allFilteredUsersSelected" :indeterminate="someFilteredUsersSelected" :disabled="!operableFilteredUsers.length" aria-label="Select operable users in the current list" @update:model-value="toggleAllFilteredUsers(Boolean($event))" /></template>
              <template #select-cell="{ row }"><UCheckbox :model-value="selectedUserIds.has(rowValue(row).id)" :disabled="!isOperableUser(rowValue(row))" :aria-label="`Select user ${rowValue(row).username}`" @update:model-value="toggleUserSelection(rowValue(row).id, Boolean($event))" /></template>
              <template #user-cell="{ row }"><p class="font-medium">{{ rowValue(row).username }}</p></template>
              <template #status-cell="{ row }"><UBadge :color="rowValue(row).deleted_at ? 'warning' : 'success'" variant="subtle">{{ rowValue(row).deleted_at ? 'Deleted' : 'Active' }}</UBadge></template>
              <template #credits-cell="{ row }"><span class="tabular-nums">{{ formatCredits(rowValue(row).credits) }}</span></template>
              <template #periodLimits-cell="{ row }"><span v-if="zeroPeriodWindows(rowValue(row)).length" class="inline-flex rounded-md border border-amber-300 bg-amber-50 px-2 py-1 text-xs font-medium text-amber-700 dark:border-amber-700 dark:bg-amber-950 dark:text-amber-300">Blocked: {{ zeroPeriodWindows(rowValue(row)).join(', ') }}</span><span v-else-if="periodWindows(rowValue(row)).length" class="inline-flex rounded-md border border-[var(--ui-border)] bg-[var(--ui-bg-muted)] px-2 py-1 text-xs text-[var(--ui-text-muted)]">{{ periodWindows(rowValue(row)).length }} windows</span><span v-else class="text-[var(--ui-text-muted)]">—</span></template>
              <template #keys-cell="{ row }">{{ keysForUser(rowValue(row).id).length }}</template>
              <template #credentialScope-cell="{ row }"><span class="block max-w-52 truncate" :title="effectiveChannelScopes(rowValue(row).id).join(', ')">{{ scopeSummary(effectiveChannelScopes(rowValue(row).id)) }}</span></template>
              <template #modelScope-cell="{ row }"><span class="block max-w-52 truncate" :title="effectiveModelScopes(rowValue(row).id).join(', ')">{{ scopeSummary(effectiveModelScopes(rowValue(row).id)) }}</span></template>
              <template #updatedAt-cell="{ row }"><span class="whitespace-nowrap text-[var(--ui-text-muted)]">{{ formatDate(rowValue(row).updated_at) }}</span></template>
              <template #actions-cell="{ row }"><RowMenu :label="rowValue(row).username" :items="userMenuItems(rowValue(row))" /></template>
              <template #empty><EmptyState icon="i-heroicons-users" text="No users match the current filter." /></template>
            </UTable>
          </div>
        </div>

        <div v-else-if="activeTab === 'keys'" class="grid gap-3 p-4">
          <div class="flex justify-end"><UButton icon="i-heroicons-plus" @click="openKeyCreate">New key</UButton></div>
          <div class="overflow-x-auto rounded-md border border-[var(--ui-border)]">
            <UTable :columns="keyColumns" :data="filteredKeys" :loading="loading" class="keys-table min-w-[920px]">
              <template #key-cell="{ row }"><div><p class="font-mono text-xs">{{ maskKey(rowValue(row).api_key) }}</p><p class="mt-1 text-xs text-[var(--ui-text-muted)]">Sequence {{ keySequence(rowValue(row)) }}</p></div></template>
              <template #owner-cell="{ row }"><span v-if="userById(rowValue(row).user_id)">{{ userById(rowValue(row).user_id).username }}</span><span v-else class="text-[var(--ui-text-muted)]">Unassigned</span></template>
              <template #credentialScope-cell="{ row }"><span class="block max-w-60 truncate">{{ scopeSummary(keyChannelNames(rowValue(row))) }}</span></template>
              <template #modelScope-cell="{ row }"><span class="block max-w-60 truncate">{{ scopeSummary(keyModelNames(rowValue(row))) }}</span></template>
              <template #length-cell="{ row }">{{ rowValue(row).api_key.length }}</template>
              <template #actions-cell="{ row }"><div class="flex justify-end gap-1.5"><UButton size="sm" color="neutral" variant="outline" icon="i-heroicons-adjustments-horizontal" @click="openKeyEdit(rowValue(row))">Set access</UButton><UButton size="sm" color="error" variant="ghost" icon="i-heroicons-trash" aria-label="Delete client key" @click="confirmKeyDelete(rowValue(row))" /></div></template>
              <template #empty><EmptyState icon="i-heroicons-key" text="No client keys yet." /></template>
            </UTable>
          </div>
        </div>

        <div v-else-if="activeTab === 'channelGroups'" class="grid gap-3 p-4">
          <UnsupportedScopes v-if="!accessGroupsSupported" />
          <template v-else>
            <div class="flex justify-end"><UButton icon="i-heroicons-plus" @click="openGroupForm('channel')">New credential scope</UButton></div>
            <GroupCards kind="channel" :groups="filteredChannelGroups" :details="channelDetailsData" :channel-groups="channelGroups" :channel-bindings-supported="modelChannelBindingsSupported" @edit="openGroupForm('channel', $event)" @delete="confirmGroupDelete('channel', $event)" @add="openBindings('credential', $event)" @delete-detail="confirmDetailDelete('channel', $event)" />
          </template>
        </div>

        <div v-else class="grid gap-3 p-4">
          <UnsupportedScopes v-if="!accessGroupsSupported" />
          <template v-else>
            <div class="flex justify-end"><UButton icon="i-heroicons-plus" @click="openGroupForm('model')">New model scope</UButton></div>
            <div class="model-scope-workspace">
              <aside class="model-scope-sidebar">
                <div class="model-scope-sidebar__header">
                  <div><p class="text-sm font-semibold">Model scopes</p><p class="mt-0.5 text-xs text-[var(--ui-text-muted)]">{{ filteredModelGroups.length }} configured</p></div>
                </div>
                <div class="model-scope-sidebar__list">
                  <button v-for="group in filteredModelGroups" :key="group.id" type="button" class="model-scope-item" :class="Number(selectedModelGroup?.id) === Number(group.id) ? 'model-scope-item--active' : ''" @click="selectedModelGroupId = group.id">
                    <span class="min-w-0 flex-1"><span class="block truncate text-sm font-medium">{{ group.group_name }}</span><span class="mt-1 flex items-center gap-1.5 text-xs text-[var(--ui-text-muted)]"><span>#{{ group.id }}</span><span>·</span><span>{{ modelDetailsFor(group.id).length }} models</span></span></span>
                    <UBadge v-if="group.disabled" color="warning" variant="subtle" size="sm">Disabled</UBadge><UIcon v-else name="i-heroicons-chevron-right" class="size-4 shrink-0 text-[var(--ui-text-dimmed)]" />
                  </button>
                  <EmptyState v-if="!filteredModelGroups.length" icon="i-heroicons-cube" text="No model scopes match the current filter." />
                </div>
              </aside>

              <section v-if="selectedModelGroup" class="model-scope-detail">
                <header class="model-scope-detail__header">
                  <div class="min-w-0"><div class="flex flex-wrap items-center gap-2"><h2 class="truncate text-base font-semibold">{{ selectedModelGroup.group_name }}</h2><UBadge :color="selectedModelGroup.disabled ? 'warning' : 'success'" variant="subtle">{{ selectedModelGroup.disabled ? 'Disabled' : 'Enabled' }}</UBadge></div><p class="mt-1 text-xs text-[var(--ui-text-muted)]">Scope #{{ selectedModelGroup.id }} · {{ selectedModelBindings.length }} selected models</p></div>
                  <div class="flex shrink-0 flex-wrap gap-1.5"><UButton size="sm" icon="i-heroicons-plus" @click="openBindings('model', selectedModelGroup)">Add models</UButton><UButton size="sm" color="neutral" variant="outline" icon="i-heroicons-pencil-square" aria-label="Edit scope" @click="openGroupForm('model', selectedModelGroup)" /><UButton size="sm" color="error" variant="ghost" icon="i-heroicons-trash" aria-label="Delete scope" @click="confirmGroupDelete('model', selectedModelGroup)" /></div>
                </header>

                <div class="model-binding-list">
                  <div class="model-binding-list__head" :class="modelChannelBindingsSupported ? 'model-binding-grid--scoped' : 'model-binding-grid--simple'"><span>Model</span><span v-if="modelChannelBindingsSupported">Credential scope</span><span>Updated</span><span class="text-right">Action</span></div>
                  <div v-for="detail in selectedModelBindings" :key="detail.id" class="model-binding-row" :class="modelChannelBindingsSupported ? 'model-binding-grid--scoped' : 'model-binding-grid--simple'">
                    <div class="min-w-0"><code class="block truncate font-mono text-xs" :title="detail.model_id">{{ detail.model_id }}</code></div>
                    <div v-if="modelChannelBindingsSupported" class="min-w-0"><span class="block truncate text-xs text-[var(--ui-text-muted)]" :title="detail.channels?.length ? detail.channels.map(channelName).join(', ') : 'Inherits key scope'">{{ detail.channels?.length ? detail.channels.map(channelName).join(', ') : 'Inherits key scope' }}</span></div>
                    <span class="whitespace-nowrap text-xs text-[var(--ui-text-muted)]">{{ formatDate(detail.updated_at) }}</span>
                    <div class="flex justify-end"><UButton size="xs" color="error" variant="ghost" icon="i-heroicons-x-mark" @click="confirmDetailDelete('model', detail)">Remove</UButton></div>
                  </div>
                  <div v-if="!selectedModelBindings.length" class="model-binding-empty"><UIcon name="i-heroicons-cube-transparent" class="mx-auto size-7 text-[var(--ui-text-dimmed)]" /><p class="mt-2 font-medium">No selected models</p><p class="mt-1 text-xs text-[var(--ui-text-muted)]">Use Add models to bind models to this scope.</p></div>
                </div>
              </section>
              <div v-else class="model-binding-empty flex min-h-80 items-center justify-center">Select a model scope from the left.</div>
            </div>
          </template>
        </div>
      </div>
    </AdminDataPanel>

    <USlideover v-model:open="userFormOpen" :title="editingUser ? 'Edit user' : 'New user'" :description="editingUser ? 'Username stays fixed after creation. This only updates password and other maintainable fields.' : 'Create an access subject that can own client keys. Password can be left blank.'" :ui="{ content: 'sm:max-w-xl' }">
      <template #body><form class="space-y-4" @submit.prevent="submitUser">
        <UAlert v-if="formError" color="error" variant="subtle" :description="formError" />
        <UFormField label="Username" :error="fieldError('username')"><UInput v-model="userForm.username" class="w-full" placeholder="user@example.com" :disabled="saving || !!editingUser" /><p v-if="editingUser" class="mt-1 text-xs text-[var(--ui-text-muted)]">Username identifies the access subject and is locked after creation. Delete and recreate the user to change it.</p></UFormField>
        <UFormField :label="editingUser ? 'New password (optional)' : 'Initial password'"><UInput v-model="userForm.password" type="password" class="w-full" placeholder="Optional. Leave blank to create the user without a password." :disabled="saving" /></UFormField>
        <UFormField label="Credits"><UInput v-model="userForm.credits" type="number" min="0" step="0.01" class="w-full" :disabled="saving || (periodLimitsSupported && userForm.credits_unlimited)" /><p class="mt-1 text-xs text-[var(--ui-text-muted)]">{{ periodLimitsSupported && userForm.credits_unlimited ? 'Unlimited mode is on: the stored balance is preserved but not enforced.' : 'Client keys bound to this user are blocked when credits are 0 or lower.' }}</p></UFormField>
        <div v-if="periodLimitsSupported" class="grid gap-3 rounded-md border border-[var(--ui-border)] p-4">
          <div><h3 class="text-sm font-semibold">Period limits</h3><p class="mt-1 text-xs text-[var(--ui-text-muted)]">Enabled windows are enforced together for every client key owned by this user.</p></div>
          <div class="flex items-center justify-between gap-3 rounded-md border border-[var(--ui-border)] px-3 py-2.5"><div><p class="text-sm font-medium">Unlimited total balance</p><p class="text-xs text-[var(--ui-text-muted)]">The total balance is not enforced or deducted; enabled period limits still apply.</p></div><USwitch v-model="userForm.credits_unlimited" :disabled="saving" /></div>
          <div v-for="window in periodWindowIds" :key="window" class="grid gap-2 rounded-md border border-[var(--ui-border)] px-3 py-2.5">
            <div class="flex items-center justify-between"><span class="text-sm font-medium">{{ periodWindowLabel(window) }}</span><USwitch v-model="userForm.periods[window].enabled" :disabled="saving" /></div>
            <div v-if="userForm.periods[window].enabled" class="grid gap-3 sm:grid-cols-2"><UFormField label="Credits limit"><UInput v-model="userForm.periods[window].limit" type="number" min="0" step="0.01" class="w-full" /></UFormField><UFormField label="Window mode"><USelect v-model="userForm.periods[window].mode" :items="periodModeOptions(window)" value-key="value" label-key="label" class="w-full" /></UFormField></div>
            <p v-if="userForm.periods[window].enabled && Number(userForm.periods[window].limit) === 0" class="text-xs text-amber-600 dark:text-amber-400">A limit of 0 blocks new requests immediately.</p>
            <div v-if="window === '7d' && userForm.periods[window].enabled && userForm.periods[window].mode === 'calendar'" class="grid gap-3 sm:grid-cols-2"><UFormField label="Week starts on"><USelect v-model="userForm.week_reset_day" :items="weekDayOptions" value-key="value" label-key="label" class="w-full" /></UFormField><UFormField label="Week start hour (0–23)"><UInput v-model="userForm.week_reset_hour" type="number" min="0" max="23" step="1" class="w-full" /></UFormField></div>
          </div>
          <UFormField label="Timezone"><USelect v-model="userForm.timezone" :items="timezoneOptions" class="w-full" /><p class="mt-1 text-xs text-[var(--ui-text-muted)]">IANA timezone used by calendar windows.</p></UFormField>
        </div>
        <div v-else class="rounded-md border border-dashed border-[var(--ui-border)] px-3 py-2.5 text-xs text-[var(--ui-text-muted)]">This runtime does not expose period-limit management. Period-limit fields will not be sent.</div>
        <div class="flex justify-end gap-2 border-t border-[var(--ui-border)] pt-4"><UButton type="button" color="neutral" variant="outline" @click="userFormOpen = false">Cancel</UButton><UButton type="submit" :loading="saving">{{ editingUser ? 'Save changes' : 'Create user' }}</UButton></div>
      </form></template>
    </USlideover>

    <USlideover v-model:open="userDetailOpen" title="User detail" description="Review this user profile, client key count, and assigned access scopes." :ui="{ content: 'sm:max-w-xl' }">
      <template #body><div v-if="userDetail" class="grid gap-5">
        <div class="rounded-md border border-[var(--ui-border)] p-4"><div class="flex flex-wrap gap-2"><UBadge :color="userDetail.deleted_at ? 'warning' : 'success'" variant="subtle">{{ userDetail.deleted_at ? 'Deleted' : 'Active' }}</UBadge><UBadge v-if="userDetail.password_set || userDetail.has_password" color="neutral" variant="subtle">Password stored</UBadge></div><p class="mt-3 font-semibold">{{ userDetail.username }}</p><p class="mt-1 text-xs text-[var(--ui-text-muted)]">User ID: {{ userDetail.id }}</p></div>
        <DetailSection title="Profile" :items="profileItems(userDetail)" />
        <section class="grid gap-3"><div class="flex items-center justify-between gap-3"><h3 class="text-sm font-semibold">Period limits</h3><UButton v-if="periodLimitsSupported" size="sm" color="neutral" variant="outline" icon="i-heroicons-arrow-path" :disabled="detailPeriodLoading || !detailPeriods" @click="openPeriodReset(userDetail)">Reset…</UButton></div><div v-if="detailPeriodLoading" class="text-sm text-[var(--ui-text-muted)]">Loading period-limit status…</div><UAlert v-else-if="detailPeriodError" color="error" variant="subtle" title="Period-limit status could not be loaded." :description="detailPeriodError" /><div v-else-if="detailPeriods" class="grid gap-3"><div class="flex flex-wrap gap-2"><UBadge color="neutral" variant="subtle">Timezone: {{ detailPeriods.timezone || userDetail.timezone || 'Asia/Shanghai' }}</UBadge><UBadge v-if="detailPeriods.credits_unlimited || detailPeriods.creditsUnlimited || userDetail.credits_unlimited" color="info" variant="subtle">Unlimited total balance</UBadge></div><PeriodCard v-for="window in normalizedDetailWindows" :key="window.id" :window="window" /></div><div v-else class="rounded-md border border-dashed border-[var(--ui-border)] px-3 py-2.5 text-xs text-[var(--ui-text-muted)]">This runtime does not expose period-limit status.</div></section>
        <DetailSection title="Access scope" :items="accessItems(userDetail)" />
      </div></template>
    </USlideover>

    <USlideover v-model:open="keyFormOpen" :title="editingKey ? 'Set client key access' : 'New client key'" :description="editingKey ? 'Assign the owner, credential scopes, and model scopes used by this client key. The secret remains unchanged.' : 'Generate a client access key and optionally assign an owner and access scopes.'" :ui="{ content: 'sm:max-w-xl' }">
      <template #body><form class="space-y-4" @submit.prevent="submitKey"><UAlert v-if="formError" color="error" variant="subtle" :description="formError" /><UFormField label="Key value"><UInput v-model="keyForm.api_key" class="w-full font-mono text-xs" :disabled="saving || !!editingKey" /></UFormField><UFormField label="Owner"><USelectMenu v-model="keyForm.user_id" :items="userOptions" value-key="value" label-key="label" class="w-full" :search-input="{ placeholder: 'Search users…' }" /></UFormField><div class="grid gap-4"><ScopePicker title="Credential scopes" empty-label="No credential scopes have been created yet." :items="channelOptions" :selected="keyForm.channels" @toggle="toggleId(keyForm.channels, $event)" /><div v-if="keyForm.channels.length" class="flex flex-wrap gap-1"><UBadge v-for="id in keyForm.channels" :key="id" color="neutral" variant="subtle">{{ channelName(id) }}</UBadge></div><ScopePicker title="Model scopes" empty-label="No model scopes have been created yet." :items="modelGroupOptions" :selected="keyForm.model_groups" @toggle="toggleId(keyForm.model_groups, $event)" /><div v-if="keyForm.model_groups.length" class="flex flex-wrap gap-1"><UBadge v-for="id in keyForm.model_groups" :key="id" color="info" variant="subtle">{{ modelGroupName(id) }}</UBadge></div></div><UAlert color="info" variant="subtle" title="Access behavior" description="No credential scopes means all credentials. No model scopes means all models. Selecting scopes restricts this client key to those assignments." /><div class="flex justify-end gap-2 border-t border-[var(--ui-border)] pt-4"><UButton type="button" color="neutral" variant="outline" @click="keyFormOpen = false">Cancel</UButton><UButton type="submit" :loading="saving">{{ editingKey ? 'Save access' : 'Create key' }}</UButton></div></form></template>
    </USlideover>

    <USlideover v-model:open="bindingOpen" :title="bindingKind === 'credential' ? 'Add credential binding' : 'Add model binding'" :description="bindingKind === 'credential' ? 'Search for and select one or more account credentials to add to this scope. Client keys bound to this scope can use those credentials.' : 'Search for and select one or more models to add to this scope. Client keys bound to this scope can use those models.'" :ui="{ content: 'sm:max-w-xl' }">
      <template #body><form class="space-y-4" @submit.prevent="addBindings"><UAlert v-if="formError" color="error" variant="subtle" :description="formError" /><div><p class="text-sm font-medium">Scope</p><div class="mt-2 rounded-md border border-[var(--ui-border)] bg-[var(--ui-bg-muted)] px-3 py-2 text-sm">{{ bindingGroupName }}</div></div><CandidatePicker :kind="bindingKind" :items="bindingCandidates" :selected="bindingSelection" :search="bindingSearch" :source-filter="modelSourceFilter" :pending="bindingKind === 'model' && modelCandidatesPending" :issue-message="bindingKind === 'model' ? modelCandidatesIssue : ''" :error-message="bindingKind === 'model' ? modelCandidatesError : ''" :mutating="saving" @update:search="bindingSearch = $event" @update:source-filter="modelSourceFilter = $event" @update:selected="setBindingSelection" @retry="loadModelCandidates" @clear-error="formError = ''" />
        <ScopePicker v-if="bindingKind === 'model' && modelChannelBindingsSupported" title="Credential scope" empty-label="No credential scopes yet." :items="channelOptions" :selected="bindingChannels" @toggle="toggleId(bindingChannels, $event)" /><p v-if="bindingKind === 'model' && modelChannelBindingsSupported" class="text-xs text-[var(--ui-text-muted)]">With nothing selected, this model binding inherits the credential scope of the client key; selections restrict dispatch to the chosen scopes.</p>
        <div class="flex justify-end gap-2 border-t border-[var(--ui-border)] pt-4"><UButton type="button" color="neutral" variant="outline" :disabled="saving" @click="bindingOpen = false">Cancel</UButton><UButton type="submit" :loading="saving" :disabled="bindingSubmitDisabled">Add binding</UButton></div></form></template>
    </USlideover>

    <USlideover v-model:open="balanceOpen" :title="balanceTargets.length > 1 ? 'Batch balance operation' : 'Balance operation'" :description="balanceTargets.length > 1 ? 'Operations are submitted one user at a time, and each user receives a separate balance record.' : 'The target user is set from the table action. Enter an amount to create a balance record.'" :ui="{ content: 'sm:max-w-xl' }">
      <template #body><form class="space-y-4" @submit.prevent="reviewBalance"><UAlert v-if="formError" color="error" variant="subtle" :description="formError" /><div><p class="text-sm font-medium">Target</p><div class="mt-2 grid gap-2 rounded-md border border-[var(--ui-border)] bg-[var(--ui-bg-muted)] px-3 py-2.5 text-sm"><SummaryRow :label="balanceTargets.length === 1 ? 'User' : 'Users'" :value="balanceTargetLabel" /><SummaryRow label="Current balance total" :value="formatCredits(balanceCurrentTotal)" /><SummaryRow label="Balance total after" :value="balanceAfterTotal == null ? '—' : formatCredits(balanceAfterTotal)" :warning="balanceAfterTotal != null && balanceAfterTotal < 0" /></div><p v-if="balanceTargets.length > 1" class="mt-2 text-xs text-[var(--ui-text-muted)]">The same amount and note will be used for each user, with separate records on the backend.</p></div><UFormField label="Operation type"><div class="grid grid-cols-2 gap-2"><UButton type="button" :color="balanceForm.type === 'recharge' ? 'primary' : 'neutral'" :variant="balanceForm.type === 'recharge' ? 'solid' : 'outline'" icon="i-heroicons-plus" @click="balanceForm.type = 'recharge'">Recharge</UButton><UButton type="button" :color="balanceForm.type === 'deduct' ? 'warning' : 'neutral'" :variant="balanceForm.type === 'deduct' ? 'solid' : 'outline'" icon="i-heroicons-minus" @click="balanceForm.type = 'deduct'">Deduct</UButton></div></UFormField><UAlert v-if="negativeBalanceCount" color="warning" variant="subtle" :description="`${negativeBalanceCount} users will have negative balances after this deduction. Home allows negative balances, but confirm this is intended.`" /><UFormField label="Amount"><UInput v-model="balanceForm.amount" type="number" min="0" step="0.000001" class="w-full" /><p class="mt-1 text-xs text-[var(--ui-text-muted)]">{{ balanceTargets.length > 1 ? 'The amount applies to each selected user.' : 'The amount applies to the current user.' }}</p></UFormField><UFormField :label="balanceFor