const GroupCards = { props: ['kind', 'groups', 'details', 'channelGroups', 'channelBindingsSupported'], emits: ['edit', 'delete', 'add', 'delete-detail'], methods: { groupDetails(group) { return this.details.filter(item => Number(item[this.kind === 'channel' ? 'channel_group_id' : 'model_group_id']) === Number(group.id) && !item.deleted_at) }, groupName(group) { return this.kind === 'channel' ? group.channel_name : group.group_name }, target(detail) { return this.kind === 'channel' ? detail.auth_id : detail.model_id }, channels(detail) { const ids = detail.channels || []; return ids.length ? ids.map(id => this.channelGroups.find(group => Number(group.id) === Number(id))?.channel_name || `#${id}`).join(', ') : 'Inherits key scope' } }, template: `<div v-if="groups.length" class="grid gap-3"><div v-for="group in groups" :key="group.id" class="rounded-md border border-[var(--ui-border)]"><div class="flex flex-col gap-3 border-b border-[var(--ui-border)] p-4 md:flex-row md:items-start md:justify-between"><div><div class="flex flex-wrap items-center gap-2"><p class="font-medium">{{ groupName(group) }}</p><UBadge color="neutral" variant="subtle">{{ groupDetails(group).length }} bindings</UBadge><UBadge v-if="group.disabled" color="warning" variant="subtle">Disabled</UBadge></div><p class="mt-1 text-xs text-[var(--ui-text-muted)]">Scope ID: {{ group.id }}</p></div><div class="flex gap-1"><UButton color="neutral" variant="ghost" size="sm" icon="i-heroicons-plus" aria-label="Add binding" @click="$emit('add', group)"/><UButton color="neutral" variant="ghost" size="sm" icon="i-heroicons-pencil-square" aria-label="Edit" @click="$emit('edit', group)"/><UButton color="error" variant="ghost" size="sm" icon="i-heroicons-trash" aria-label="Delete" @click="$emit('delete', group)"/></div></div><div class="overflow-x-auto"><table class="w-full min-w-[620px] table-fixed text-sm"><thead class="bg-[var(--ui-bg-muted)] text-left text-xs text-[var(--ui-text-muted)]"><tr><th class="w-[52%] p