async function resetPeriods() { if (!resetWindows.value.size) return void (formError.value = 'Select at least one window.'); saving.value = true; try { detailPeriods.value = await fetchAPI(`/users/${periodResetUser.value.id}/period-limits/reset`, { method: 'POST', body: { windows: periodWindowIds.filter(id => resetWindows.value.has(id)), mode: resetMode.value } }); periodResetOpen.value = false; await syncAll(); toast.add({ title: 'Period counters reset.', color: 'success' }) } catch (error) { formError.value = errorMessage(error) } finally { saving.value = false } }

const deleteOpen = ref(false), deleteKind = ref(''), deleteTarget = ref(null)
const deleteDescription = computed(() => { const target = deleteTarget.value; if (!target) return ''; if (deleteKind.value === 'user') return `Delete user “${target.username}”? This will not automatically delete global credentials.`; if (deleteKind.value === 'key') return `Delete client key ${maskKey(target.api_key)}? Linked clients will stop working immediately.`; if (deleteKind.value === 'detail') return `Delete binding “${target.auth_id || target.model_id}”?`; return `Delete scope “${target.channel_name || target.group_name}”? Bound keys will lose this scope reference.` })
function openDelete(kind, target, subkind = '') { deleteKind.value = kind; deleteTarget.value = { ...target, subkind }; deleteOpen.value = true }
function confirmUserDelete(user) { openDelete('user', user) } function confirmKeyDelete(key) { openDelete('key', key) } function confirmGroupDelete(kind, group) { openDelete('group', group, kind) } function confirmDetailDelete(kind, detail) { openDelete('detail', detail, kind) }
async function performDelete() { const target = deleteTarget.value; if (!target) return; let url = ''; if (deleteKind.value === 'user') url = `/users/${target.id}`; if (deleteKind.value === 'key') url = `/api-keys?id=${encodeURIComponent(target.id)}`; if (deleteKind.value === 'group') url = `/${target.subkind === 'channel' ? 'channel-groups' : 'model-groups'}/${target.id}`; if (deleteKind.value === 'detail') url = `/${target.subkind === 'channel' ? 'channel-group-details' : 'model-group-details'}/${target.id}`; saving.value = true; try { await fetchAPI(url, { method: 'DELETE' }); deleteOpen.value = false; await syncAll(); toast.add({ title: deleteKind.value === 'detail' ? 'Binding deleted.' : deleteKind.value === 'group' ? 'Scope deleted.' : deleteKind.value === 'key' ? 'Client key deleted.' : 'User deleted.', color: 'success' }) } catch (error) { toast.add({ title: 'Delete failed', description: errorMessage(error), color: 'error' }) } finally { saving.value = false } }
</script>

